package app.kinnect.audit;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;import java.io.*;import java.util.concurrent.*;
public class LayoutAudit extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{
  Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1200);
  for(String sort:new String[]{"following","interests"}){
   final View[] empty=new View[1];runOnMainSync(()->{try{Field field=a.getClass().getDeclaredField("discoverSort");field.setAccessible(true);field.set(a,sort);Method method=a.getClass().getDeclaredMethod("discoveryEmptyState");method.setAccessible(true);empty[0]=(View)method.invoke(a);FrameLayout canvas=new FrameLayout(a);canvas.setBackgroundColor(0xfff6f5fa);int inset=Math.round(16*a.getResources().getDisplayMetrics().density);canvas.setPadding(inset,inset,inset,inset);canvas.addView(empty[0],new FrameLayout.LayoutParams(-1,-2));a.setContentView(canvas);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();CountDownLatch painted=new CountDownLatch(1);runOnMainSync(()->empty[0].postOnAnimation(()->empty[0].postOnAnimation(painted::countDown)));if(!painted.await(5,TimeUnit.SECONDS))throw new AssertionError("No painted frame");
   runOnMainSync(()->{LinearLayout box=(LinearLayout)empty[0];int[] parent=new int[2];box.getLocationOnScreen(parent);for(int i=0;i<box.getChildCount();i++){View child=box.getChildAt(i);if(child instanceof TextView){TextView text=(TextView)child;if((text.getGravity()&Gravity.HORIZONTAL_GRAVITY_MASK)!=Gravity.CENTER_HORIZONTAL)throw new AssertionError("Text not centered: "+text.getText());int[] at=new int[2];child.getLocationOnScreen(at);if(Math.abs((at[0]+child.getWidth()/2f)-(parent[0]+box.getWidth()/2f))>1)throw new AssertionError("Text box offset");}}});
   File file=new File(a.getExternalFilesDir(null),"empty-"+sort+".png");try(FileOutputStream stream=new FileOutputStream(file)){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,stream);}result.putString(sort,file.getAbsolutePath());
  }for(String screen:new String[]{"appearanceScreen","securityScreen","aboutScreen","auth-login","auth-signup","intro","meMenu","settings","nativeNotificationSettings","helpScreen","changePassword"}){
   runOnMainSync(()->{try{Field me=a.getClass().getDeclaredField("me");me.setAccessible(true);me.set(a,new org.json.JSONObject().put("id","layout-local").put("name","Người kiểm tra chữ và bố cục").put("username","layout_audit").put("dmMode","everyone"));if(screen.startsWith("auth-")){Method method=a.getClass().getDeclaredMethod("auth",boolean.class);method.setAccessible(true);method.invoke(a,screen.equals("auth-signup"));}else{Method method=a.getClass().getDeclaredMethod(screen);method.setAccessible(true);method.invoke(a);}}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();CountDownLatch frame=new CountDownLatch(1);runOnMainSync(()->a.getWindow().getDecorView().postOnAnimation(()->a.getWindow().getDecorView().postOnAnimation(frame::countDown)));if(!frame.await(5,TimeUnit.SECONDS))throw new AssertionError("No screen frame");File shot=new File(a.getExternalFilesDir(null),"audit-"+screen+".png");try(FileOutputStream out=new FileOutputStream(shot)){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}result.putString(screen,shot.getAbsolutePath());
  }
  result.putString("result","PASS: both actual APK discovery empty-state titles and descriptions centered after rendering");finish(Activity.RESULT_OK,result);
 }catch(Throwable t){result.putString("error",t.toString());finish(Activity.RESULT_CANCELED,result);}}
}
